import csv, math, glob, os, statistics

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def cal_slope(path):
    rows = read_csv(path)
    xs = [float(r['mass_g'])/1000*9.81 for r in rows]
    ys = [float(r['voltage_V']) for r in rows]
    n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    b=sxy/sxx; a=my-b*mx
    resid=[y-(a+b*x) for x,y in zip(xs,ys)]
    return b, a, max(abs(r) for r in resid), max(xs)

def rho_w(T):
    return 1000.0*(1.0-(T+288.9414)/(508929.2*(T+68.12963))*(T-3.9863)**2)
def mu_w(T):
    return 2.414e-5*10.0**(247.8/(T+273.15-140.0))
def nu_w(T):
    return mu_w(T)/rho_w(T)

def load_run(path, batch):
    if batch=='2026-03-12':
        with open(path) as f:
            next(f)
            rows=[line.strip().split(';') for line in f if line.strip()]
        return [float(r[0]) for r in rows], [float(r[1]) for r in rows]
    with open(path) as f:
        lines=[l for l in f if not l.startswith('#') and l.strip()]
    rows=list(csv.DictReader(lines))
    return [float(r['time_s']) for r in rows], [float(r['loadcell_V']) for r in rows]

cals={k:cal_slope(v) for k,v in {
 '2025-09':'data/calibration/loadcell_2025-09.csv',
 '2026-03':'data/calibration/loadcell_2026-03.csv'}.items()}
for k,v in cals.items(): print('cal',k,v)
batchcal={'2025-10-14':'2025-09','2025-11-03':'2025-09','2026-03-12':'2026-03'}

log={}
for r in read_csv('data/run_log.csv'):
    log[int(r['run_id'])]=r

rows=[]
for path in sorted(glob.glob('data/raw/*/run_*.csv')):
    batch=os.path.basename(os.path.dirname(path))
    run=int(os.path.basename(path)[4:7])
    t,v=load_run(path,batch)
    sens=cals[batchcal[batch]][0]
    pre=[vv for tt,vv in zip(t,v) if 0<=tt<1]
    post=[vv for tt,vv in zip(t,v) if 10.5<=tt<11.9]
    pre_m=sum(pre)/len(pre); post_m=sum(post)/len(post)
    steady=[vv for tt,vv in zip(t,v) if 3<=tt<=8]
    F=[(vv-pre_m)/sens for vv in steady]
    Fm=sum(F)/len(F); Fsd=statistics.pstdev(F)
    D=float(log[run]['diameter_mm'])/1000
    U=float(log[run]['speed_m_s']); T=float(log[run]['water_temp_c'])
    rho=rho_w(T); nu=nu_w(T); area=D*0.60
    Re=U*D/nu; Cd=Fm/(0.5*rho*U*U*area)
    # linear baseline
    t0=0.5; t1=(10.5+11.9)/2
    Flin=[]
    for tt,vv in zip(t,v):
        if 3<=tt<=8:
            base=pre_m+(post_m-pre_m)*(tt-t0)/(t1-t0)
            Flin.append((vv-base)/sens)
    Cdlin=(sum(Flin)/len(Flin))/(0.5*rho*U*U*area)
    rows.append(dict(run=run,batch=batch,cyl=log[run]['cylinder'],D=D,U=U,T=T,rho=rho,nu=nu,
                     Re=Re,F=Fm,Fsd=Fsd,Cd=Cd,Cdlin=Cdlin,drift_mV=(post_m-pre_m)*1e3,
                     drift_N=(post_m-pre_m)/sens))

print('\nper-run:')
for r in rows:
    print(f"{r['run']:2d} {r['cyl']:5s} U={r['U']:.1f} T={r['T']:.1f} nu={r['nu']*1e6:.4f}e-6 Re={r['Re']:8.0f} F={r['F']:7.3f} Cd={r['Cd']:.3f} Cdlin={r['Cdlin']:.3f} drift={r['drift_mV']:6.2f}mV/{r['drift_N']:6.3f}N")

paper=[r for r in rows if r['run']!=17]
print('\nsummary (exclude 17):')
for cyl in ['1in','1.5in','2in']:
    g=[r for r in paper if r['cyl']==cyl]
    cs=[r['Cd'] for r in g]
    print(cyl,len(g),f"Re {min(r['Re'] for r in g):.0f}-{max(r['Re'] for r in g):.0f}",f"Cd {sum(cs)/len(cs):.3f} +/- {statistics.pstdev(cs):.3f}",f"T {min(r['T'] for r in g)}-{max(r['T'] for r in g)}")
cs=[r['Cd'] for r in paper]
print('overall',len(cs),f"Re {min(r['Re'] for r in paper):.0f}-{max(r['Re'] for r in paper):.0f}",f"Cd {sum(cs)/len(cs):.3f} +/- {statistics.pstdev(cs):.3f}")

print('\nrun17 details: pre/post', )
for r in rows:
    if r['run']==17: print(r)

